@js:
var cfg = {};
try { cfg = JSON.parse(String(source.getVariable() || '{}')) || {}; } catch (e) {}

var CH = [['男频', '♂', 1], ['女频', '♀', 2], ['出版', '✎', 3]];
var ch = CH.filter(function (c) { return c[0] == cfg.ch; })[0] || CH[0];

var cache = cfg.cat || {};
var data = cfg.fast && cache[ch[2]];
if (!data || !data.g) {
    data = {g: [], r: []};
    try {
        data.g = JSON.parse(java.ajax(qmIndex(ch[2]))).data.category_list.map(function (g) {
            return [String(g.title), g.list.filter(function (c) {
                return c.category_type == '2' && c.category_id;
            }).map(function (c) { return [String(c.title), String(c.category_id)]; })];
        }).filter(function (g) { return g[1].length; });
    } catch (e) {}
    try {
        JSON.parse(java.ajax(qmRankIndex(ch[2]))).data.rank_list.forEach(function (r) {
            if (r.type == 'character_list' || r.show_type == '6') return;
            data.r.push([String(r.title), String(r.type) + ((r.sub_titles || []).length > 1 ? '|month' : '')]);
        });
    } catch (e) {}
    if (ch[2] == 1 || ch[2] == 2) {
        data.r.push(['殿堂作品', 'sp:hall'], ['原创风云榜', 'sp:award'], ['宗师作家', 'sp:master']);
    }
    if (ch[2] == 2) {
        try {
            JSON.parse(java.ajax(qmStoryIndex())).data.rank_list.forEach(function (r) {
                data.r.push(['短篇' + r.title, 'story:' + r.type]);
            });
        } catch (e) {}
    }
    if (data.g.length) cache[ch[2]] = data;
}
var groups = data.g, ranks = data.r;
cfg.cat = cache;
delete cfg.fast;
source.setVariable(JSON.stringify(cfg));

var open = cfg.open || {};
var over = cfg.over || '-99', words = cfg.words || '-99', sort = cfg.sort || '0';

var OVER = [['全部状态', '-99'], ['完结', '1'], ['连载', '0']];
var WORDS = [['全部字数', '-99'], ['50万以下', '1'], ['50-100万', '2'], ['100-300万', '3'], ['300万以上', '4']];
var SORT = [['按热度', '0'], ['按更新', '1'], ['按评分', '2'], ['按新书', '3']];
function label(opts, v) { return (opts.filter(function (o) { return o[1] == v; })[0] || opts[0])[0]; }

var LAYOUT = {gap: 0.042, pad: 0.068, ch: 0.0368, shortMax: 3.3};

function textWidth(t) {
    var w = 0;
    for (var i = 0; i < t.length; i++) {
        var c = t.charCodeAt(i);
        if (c == 32) w += 0.32;
        else if (c < 128) w += 0.65;
        else if (c == 0xB7) w += 0.5;
        else if (c == 0x25CF) w += 0.9;
        else w += 1;
    }
    return w;
}

var s = [];

function pack(items, cols) {
    cols = cols || 4;
    var g = LAYOUT.gap, cell = (1 - g * (cols - 1)) / cols;
    var fit = (cell - LAYOUT.pad) / LAYOUT.ch;
    var queue = items.map(function (it) {
        return {it: it, span: Math.min(cols, Math.ceil(textWidth(it.title) / fit) || 1)};
    });
    while (queue.length) {
        var row = [], left = cols;
        while (queue.length && left > 0) {
            var k = 0;
            while (k < queue.length && queue[k].span > left) k++;
            if (k == queue.length) break;
            var x = queue.splice(k, 1)[0];
            row.push(x); left -= x.span;
        }
        for (; left > 0; left--) row.push({it: {title: '　', url: ''}, span: 1});
        row.forEach(function (x, i) {
            var st = {layout_flexGrow: x.span, layout_flexBasisPercent: Math.round((x.span / (cols + 1) + (x.span - 1) * g) * 1e4) / 1e4};
            if (i == 0) st.layout_wrapBefore = true;
            x.it.style = st;
            s.push(x.it);
        });
    }
}

function action(js) {
    return "(function(){var c={};try{c=JSON.parse(String(source.getVariable()||'{}'))||{};}catch(e){}"
        + js + "c.fast=1;source.setVariable(JSON.stringify(c));java.refreshExplore();})()";
}
function button(title, js) {
    return {title: title, type: 'button', action: action(js)};
}
function bar(title, js) {
    var b = button(title, js);
    b.style = {layout_flexGrow: 1, layout_flexBasisPercent: 1, layout_wrapBefore: true};
    s.push(b);
}
function optionRow(key, opts, cur) {
    pack(opts.map(function (o) {
        return button((o[1] == cur ? '● ' : '') + o[0], 'c[' + JSON.stringify(key) + ']=' + JSON.stringify(o[1]) + ';');
    }), 3);
}

pack(CH.map(function (c) {
    return button((c[0] == ch[0] ? '● ' : '') + c[1] + ' ' + c[0], 'c.ch=' + JSON.stringify(c[0]) + ';');
}), 3);

var filterTitle = '⚙ 筛选：' + label(OVER, over) + ' · ' + label(WORDS, words) + ' · ' + label(SORT, sort);
bar(filterTitle + (cfg.filt ? '　▾' : '　▸'), 'c.filt=!c.filt;');
if (cfg.filt) {
    optionRow('over', OVER, over);
    optionRow('words', WORDS, words);
    optionRow('sort', SORT, sort);
}

if (!groups.length) s.push({title: '⚠ 分类加载失败', url: '', style: {layout_flexGrow: 1, layout_flexBasisPercent: 1, layout_wrapBefore: true}});

function split(items) {
    var short = [], long = [];
    items.forEach(function (it) { (textWidth(it.title) > LAYOUT.shortMax ? long : short).push(it); });
    pack(short, 4);
    pack(long, 3);
}

if (ranks.length) {
    var rkey = ch[0] + '|排行';
    var rOpen = !!open[rkey];
    bar((rOpen ? '▾ ' : '▸ ') + '排行（' + ranks.length + '）',
        'var o=c.open||{};o[' + JSON.stringify(rkey) + ']=' + (rOpen ? 0 : 1) + ';c.open=o;');
    if (rOpen) split(ranks.map(function (r) {
        var t = r[1].split(':'), url;
        if (t[0] == 'sp') url = "{{qmSpecial('" + t[1] + "'," + ch[2] + ',page)}}';
        else if (t[0] == 'story') url = "{{qmStoryRank('" + t[1] + "',page)}}";
        else url = '{{qmRank(' + ch[2] + ",'" + r[1].split('|')[0] + "',page,'" + (r[1].split('|')[1] || '') + "')}}";
        return {title: r[0], url: url};
    }));
}

groups.forEach(function (g, gi) {
    var key = ch[0] + '|' + g[0];
    var isOpen = key in open ? !!open[key] : gi == 0;
    bar((isOpen ? '▾ ' : '▸ ') + g[0] + '（' + g[1].length + '）',
        'var o=c.open||{};o[' + JSON.stringify(key) + ']=' + (isOpen ? 0 : 1) + ';c.open=o;');
    if (!isOpen) return;
    split(g[1].map(function (kv) {
        return {title: kv[0], url: '{{qmTag(' + ch[2] + ',' + kv[1] + ',page,' + over + ',' + words + ',' + sort + ')}}'};
    }));
});

JSON.stringify(s);

