var QM_KEY = 'd3dGiJc651gSQ8w1';
var QM_AES = '242ccb8230d709e1';
var QM_BC = 'https://api-bc.wtzw.com';
var QM_KS = 'https://api-ks.wtzw.com';

function qmMd5(s) {
    var b = Packages.java.security.MessageDigest.getInstance('MD5')
        .digest(new Packages.java.lang.String(s).getBytes('UTF-8'));
    var h = '';
    for (var i = 0; i < b.length; i++) {
        var x = (b[i] & 0xff).toString(16);
        h += (x.length < 2 ? '0' : '') + x;
    }
    return h;
}

function qmSign(o) {
    return qmMd5(Object.keys(o).sort().map(function (k) { return k + '=' + o[k]; }).join('') + QM_KEY);
}

var QM_HEADERS = (function () {
    var h = {'app-version': '80400', 'platform': 'android', 'reg': '0', 'AUTHORIZATION': '',
             'application-id': 'com.****.reader', 'net-env': '1', 'channel': 'unknown', 'qm-params': ''};
    h.sign = qmSign(h);
    return JSON.stringify({headers: h});
})();

function qmUrl(base, path, params) {
    params.sign = qmSign(params);
    var q = Object.keys(params).map(function (k) {
        return k + '=' + encodeURIComponent(params[k]);
    }).join('&');
    return base + path + '?' + q + ',' + QM_HEADERS;
}

function qmSearch(key, page) {
    return qmUrl(QM_BC, '/search/v1/words', {gender: '3', imei_ip: '2937357107', page: page, wd: key});
}
function qmDetail(id) {
    return qmUrl(QM_BC, '/api/v4/book/detail', {id: id, imei_ip: '2937357107', teeny_mode: 0});
}
function qmToc(id) {
    return qmUrl(QM_KS, '/api/v1/chapter/chapter-list', {id: id});
}
function qmTag(gender, tid, page, over, words, sort) {
    var p = {gender: gender, need_filters: 1, page: page, tag_id: tid,
        over: over == null ? -99 : over, words: words == null ? -99 : words, sort: sort == null ? 0 : sort};
    if (gender == 1 || gender == 2) p.book_preference = gender;
    return qmUrl(QM_BC, '/api/v4/tag/index', p);
}

function qmIndex(tab) {
    return qmUrl(QM_BC, '/api/v5/category/index', {gender: '2', tab_type: tab, read_preference: '0', book_privacy: '1', category_new_hot: '0'});
}

function qmForm(base, path, params) {
    params.sign = qmSign(params);
    var body = Object.keys(params).map(function (k) {
        return k + '=' + encodeURIComponent(params[k]);
    }).join('&');
    var h = JSON.parse(QM_HEADERS).headers;
    h['Content-Type'] = 'application/x-www-form-urlencoded';
    return base + path + ',' + JSON.stringify({method: 'POST', body: body, headers: h});
}

function qmRankIndex(tab) {
    return qmUrl(QM_BC, '/api/v1/leader-board', {rank_type: '', category_id: 0, category_type: 0, tab_type: tab, imei_ip: '2937357107', book_privacy: 1, read_preference: 0});
}

function qmStoryIndex() {
    return qmUrl(QM_BC, '/api/v1/story/leader-board', {rank_type: '', category_id: 0, category_type: 0, page_no: 1, book_privacy: 1});
}

function qmRank(tab, type, page, period) {
    var p = {rank_type: type, category_id: 0, category_type: 0, tab_type: tab, imei_ip: '2937357107', book_privacy: 1, read_preference: 0, page_no: page};
    if (period == 'month') p.list_type = 'month';
    return qmUrl(QM_BC, '/api/v1/leader-board', p);
}

function qmStoryRank(type, page) {
    return qmUrl(QM_BC, '/api/v1/story/leader-board', {rank_type: type, category_id: 0, category_type: 0, page_no: page, book_privacy: 1});
}

function qmSpecial(kind, gender, page) {
    if (kind == 'award') return qmUrl(QM_BC, '/api/v1/h5/book-original-award/list', {gender: gender, page: page});
    if (kind == 'hall') return qmUrl(QM_BC, '/api/v1/h5/hall-of-fame/list', {gender: gender, page_no: page});
    return qmUrl(QM_BC, '/api/v1/h5/original-author-master/list', {page_no: page});
}

function qmParam(url, k) {
    var m = String(url).match(new RegExp('[?&]' + k + '=([^&,]*)'));
    return m ? decodeURIComponent(m[1]) : '';
}

function qmItem(o) {
    var tags = o.ptags;
    if (!tags && o.book_title) tags = (o.type == 1 ? '宗师作家' : '大师作家') + ' · ' + o.year;
    if (!tags) tags = [o.sub_title, o.heat_number].filter(function (v) { return v; }).join(' · ');
    return {
        id: String(o.id || o.book_id || ''),
        title: String(o.title || o.book_title || ''),
        author: String(o.author || o.author_name || ''),
        image_link: String(o.image_link || o.img || ''),
        intro: String(o.intro || o.rec_desc || ''),
        ptags: String(tags || ''),
        words_num: String(o.words_num || '')
    };
}

function qmFill(items, java) {
    var need = items.filter(function (o) { return o.id && (!o.author || !o.intro || !o.ptags); });
    for (var i = 0; i < need.length; i += 10) {
        var batch = need.slice(i, i + 10);
        var res = [];
        try { res = java.ajaxAll(batch.map(function (o) { return qmDetail(o.id); })); } catch (e) {}
        batch.forEach(function (o, j) {
            try {
                var b = JSON.parse(String(res[j].body())).data.book;
                if (!o.author) o.author = String(b.author || '');
                if (!o.intro) o.intro = String(b.intro || '');
                if (!o.words_num) o.words_num = String(b.words_num || '');
                if (!o.ptags) o.ptags = String(b.category_over_words || '');
            } catch (e) {}
        });
    }
    return items;
}

function qmList(result, url, java) {
    url = String(url);
    var page = parseInt(qmParam(url, 'page') || qmParam(url, 'page_no')) || 1;
    var d = {};
    try { d = JSON.parse(result).data || {}; } catch (e) {}
    var list = d.books || [];
    if (url.indexOf('/tag/index') >= 0 && !list.length) {
        var p = {
            category_id: qmParam(url, 'tag_id'), category_type: '2', gender: qmParam(url, 'gender'),
            need_filters: '1', page: String(page), book_privacy: '1', from: '4', read_preference: '0',
            over: qmParam(url, 'over') || '-99', words: qmParam(url, 'words') || '-99',
            sort: {'0': '1', '1': '3', '2': '2', '3': '4'}[qmParam(url, 'sort')] || '1'
        };
        if (qmParam(url, 'book_preference')) p.book_preference = qmParam(url, 'book_preference');
        try { list = (JSON.parse(java.ajax(qmForm(QM_BC, '/api/v5/category/get-list', p))).data || {}).books || []; } catch (e) {}
    } else if (url.indexOf('/story/leader-board') >= 0) {
        if (page > 1 && !d.refresh_page) list = [];
    } else if (url.indexOf('original-author-master') >= 0) {
        list = page > 1 ? [] : (d.list || []);
    } else if (url.indexOf('hall-of-fame') >= 0 || url.indexOf('/leader-board') >= 0) {
        if (page > 1) list = [];
        else if (qmParam(url, 'list_type') == 'month') list = d.month_books || [];
    }
    return qmFill(list.map(qmItem), java).map(function (o) { return JSON.stringify(o); });
}

function qmContent(bid, cid, agent) {
    var p = {id: bid, chapterId: cid};
    if (agent) p.reader_agent = '1';
    return qmUrl(QM_KS, '/api/v1/chapter/content', p);
}

function qmChapterUrl(cid, md5, agent) {
    var s = cid + '/' + md5 + '/' + (agent == '1' ? '1' : '0');
    var b64 = Packages.java.util.Base64.getEncoder()
        .encodeToString(new Packages.java.lang.String(s).getBytes('UTF-8'));
    return 'data:;base64,' + b64 + ',{"type":"qm"}';
}

function qmUnzipEpub(b) {
    function u16(p) { return (b[p] & 0xff) | (b[p + 1] & 0xff) << 8; }
    function u32(p) { return (u16(p) | u16(p + 2) << 16) >>> 0; }
    var eocd = b.length - 22;
    while (eocd >= 0 && u32(eocd) != 0x06054b50) eocd--;
    if (eocd < 0) return '';
    var p = u32(eocd + 16), count = u16(eocd + 10), html = '';
    for (var i = 0; i < count; i++) {
        var method = u16(p + 10), csize = u32(p + 20), usize = u32(p + 24);
        var nlen = u16(p + 28), total = 46 + nlen + u16(p + 30) + u16(p + 32);
        var name = String(new Packages.java.lang.String(b, p + 46, nlen, 'UTF-8'));
        var lh = u32(p + 42);
        p += total;
        if (!/\.x?html?$/i.test(name)) continue;
        var start = lh + 30 + u16(lh + 26) + u16(lh + 28), text;
        if (method == 0) {
            text = new Packages.java.lang.String(b, start, csize, 'UTF-8');
        } else {
            var inf = new Packages.java.util.zip.Inflater(true);
            inf.setInput(b, start, csize);
            var out = Packages.java.util.Arrays.copyOf(b, usize);
            inf.inflate(out);
            inf.end();
            text = new Packages.java.lang.String(out, 'UTF-8');
        }
        var m = String(text).match(/<body[^>]*>([\s\S]*)<\/body>/i);
        if (m) html += m[1];
    }
    return html.replace(/<h\d[^>]*>[\s\S]*?<\/h\d>/gi, '')
               .replace(/&amp;/g, '&').trim();
}

function qmDecode(content) {
    var A = Packages.java.util.Arrays;
    var raw = Packages.java.util.Base64.getDecoder().decode(String(content));
    var key = new Packages.javax.crypto.spec.SecretKeySpec(new Packages.java.lang.String(QM_AES).getBytes('UTF-8'), 'AES');
    var iv = new Packages.javax.crypto.spec.IvParameterSpec(A.copyOfRange(raw, 0, 16));
    var c = Packages.javax.crypto.Cipher.getInstance('AES/CBC/PKCS5Padding');
    c.init(2, key, iv);
    var b = c.doFinal(A.copyOfRange(raw, 16, raw.length));
    if (b.length > 3 && b[0] == 0x50 && b[1] == 0x4B) return qmUnzipEpub(b);
    return String(new Packages.java.lang.String(b, 'UTF-8'));
}

