var seg = String(java.hexDecodeToString(result)).split('/');
var bid = String(java.get('bid'));
var story = seg[2] == '1';
var out;
try {
    var res = JSON.parse(java.ajax(qmContent(bid, seg[0], story)));
    if (!(res.data && res.data.content)) res = JSON.parse(java.ajax(qmContent(bid, seg[0], !story)));
    out = (res.data && res.data.content) ? qmDecode(res.data.content)
        : '七猫服务器未返回本章正文：' + (res.errors ? res.errors.details : '未知错误');
} catch (e) {
    out = '正文获取失败：' + e;
}
out;
